// Mock os.Exit for testing
func captureOutput(f func()) (string, int) {
	oldStdout := os.Stdout
	oldStderr := os.Stderr
	oldExit := os.Exit

	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w

	exitCode := 0
	os.Exit = func(code int) {
		exitCode = code
		panic("os.Exit was called") // Panic to stop execution without actually exiting
	}

	defer func() {
		os.Stdout = oldStdout
		os.Stderr = oldStderr
		os.Exit = oldExit
		w.Close()
	}()

	out := make(chan string)
	go func() {
		var buf []byte
		io.Copy(&buf, r)
		out <- string(buf)
	}()

	func() {
		defer func() {
			if r := recover(); r != nil {
				if r != "os.Exit was called" {
					panic(r)
				}
			}
		}()
		f()
	}()

	w.Close()
	output := <-out
	return output, exitCode
