	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w

	outBuf := new(bytes.Buffer)
	errBuf := new(bytes.Buffer)
	writers := io.MultiWriter(outBuf, errBuf)

	exitCode := 0
